  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(200) DEFAULT NULL,
  `descripcion` text,
  `precio` double DEFAULT NULL,
  `beneficios` mediumtext,
  `aforo` int DEFAULT NULL,
  `imagen` longblob,
